import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return
    n = int(input_data[0])
    commands = input_data[1:n+1]

    results = []
    for command in commands:
        if command.startswith("Simon says "):
            results.append(command[10:])

    print("\n".join(results))

if __name__ == "__main__":
    main()
